from collections import Counter, deque


def transform(grid):
    """Fill background pockets enclosed by the colored outline and/or grid edge."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    wall_colors = {value for value in counts if value != background}

    unseen = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == background}
    result = [row[:] for row in grid]
    while unseen:
        start = unseen.pop()
        component = {start}
        queue = deque([start])
        while queue:
            r, c = queue.popleft()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if (nr, nc) in unseen:
                    unseen.remove((nr, nc))
                    component.add((nr, nc))
                    queue.append((nr, nc))

        r0 = min(r for r, _ in component)
        r1 = max(r for r, _ in component)
        c0 = min(c for _, c in component)
        c1 = max(c for _, c in component)
        edges = set()
        if r0 == 0: edges.add("top")
        if r1 == h - 1: edges.add("bottom")
        if c0 == 0: edges.add("left")
        if c1 == w - 1: edges.add("right")
        enclosed = not edges

        # A cavity may use one grid edge as its final side. Requiring exactly
        # one touched edge avoids treating broad exterior corner regions as holes.
        if len(edges) == 1 and r1 > r0 and c1 > c0:
            rim = []
            for c in range(c0, c1 + 1):
                rim.extend(((r0 - 1, c), (r1 + 1, c)))
            for r in range(r0, r1 + 1):
                rim.extend(((r, c0 - 1), (r, c1 + 1)))
            enclosed = all(
                not (0 <= r < h and 0 <= c < w) or grid[r][c] in wall_colors
                for r, c in rim
            )

        if enclosed:
            for r, c in component:
                result[r][c] = 4
    return result

