def fill_holes(grid, diagonals=False):
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    q=deque();seen=set()
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if diagonals: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    for r in range(h):
      for c in range(w):
        if (r in (0,h-1) or c in (0,w-1)) and grid[r][c]==bg and (r,c) not in seen:
          seen.add((r,c));q.append((r,c))
    while q:
      r,c=q.popleft()
      for dr,dc in dirs:
        nr,nc=r+dr,c+dc
        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
          seen.add((nr,nc));q.append((nr,nc))
    return [[4 if x==bg and (r,c) not in seen else x for c,x in enumerate(row)] for r,row in enumerate(grid)]
